/**
 * The bundled synthetic sample configs (samples/dead-configs), one tombstone each.
 * manifest.json is generated by `npm run samples` from the engine's own exhume output.
 */
import type { Crypt } from "../api/hooks";
import type { DialectName } from "../api/types";

import asa82 from "../../../samples/dead-configs/asa-8.2-branch.cfg?raw";
import asa98 from "../../../samples/dead-configs/asa-9.8-dc.cfg?raw";
import ios12 from "../../../samples/dead-configs/ios-12-edge.cfg?raw";
import pix63 from "../../../samples/dead-configs/pix-2006-hq.cfg?raw";
import manifest from "./manifest.json";

export interface SampleEntry {
  id: string;
  file: string;
  dialect: DialectName;
  os_version: string;
  rules: number;
  died: number; // fictional, part of the theme
  sha256: string; // of the raw file, checked by samples.test.ts
}

export const RAW_SAMPLES: Readonly<Record<string, string>> = {
  "asa-8.2-branch.cfg": asa82,
  "asa-9.8-dc.cfg": asa98,
  "ios-12-edge.cfg": ios12,
  "pix-2006-hq.cfg": pix63,
};

export interface SampleCrypt extends Crypt {
  sample: SampleEntry;
}

export const SAMPLE_ENTRIES = manifest as SampleEntry[];

/** Samples in a fixed order: oldest death first, then by name. */
export const SAMPLES: readonly SampleCrypt[] = [...SAMPLE_ENTRIES]
  .sort((a, b) => a.died - b.died || a.id.localeCompare(b.id))
  .map((entry) => {
    const config = RAW_SAMPLES[entry.file];
    if (config === undefined) throw new Error(`sample ${entry.file} is not bundled`);
    return { id: `sample:${entry.id}`, name: entry.id, config, sample: entry };
  });
